\SetAlgoLined
\KwIn{Benchmark $\mathcal{B}$, reference subsample $\mathcal{R}$, scFM $\theta$, donor and cell-type metadata.}
\KwOut{Per-cell $\{J^\ast(c), p_c\}$; donor-matched gap statistics and permutation $p$.}
\textbf{Step 1 (Signal A):} Compute MinHash sketch ($m = 128$) for each $c \in \mathcal{B} \cup \mathcal{R}$\;
\For{$c \in \mathcal{B}$}{
  Compute $J^\ast(c)$ via banded LSH ($b = 16$, $r = 8$) on $\mathcal{R}$\;
  Draw $1000$ permutation sketches; compute $p_c$ from Eq.~\ref{eq:pval}\;
}
\textbf{Step 2 (Embedding):} Extract $\theta$-embedding $\mathbf{e}_c$ for all $c \in \mathcal{B}$\;
\textbf{Step 3 (Donor-matched gap):}\;
\For{each $(t, d)$ pair with $n_{\text{clean}}, n_{\text{contam}} \geq n_{\min}$}{
  Compute $\Delta_{(t, d), \theta}$ via Eq.~\ref{eq:per-pair-gap}\;
}
\textbf{Step 4 (Permutation null):} Shuffle contamination labels within each $(t, d)$ group, repeat Step 3, $B = 500$ trials\;
\textbf{Step 5 (Negative control, optional):} Repeat Steps 3--4 on a Signal-A-clean dataset with random pseudo-contamination\;
\caption{scContam audit pipeline}
\label{alg:scontam}
\end{algorithm}
